import * as THREE from './three.module.js';
export function createAtmosphere({scene,camera,renderer,sun,water,box,colliders,rand,clouds,toast}) {
 const mobile=matchMedia('(max-width: 700px)').matches;
 const state={time:0,night:0,targetNight:0,quality:mobile?'balanced':'high',firstPerson:false,immersive:false};
 const hemi=scene.children.find(o=>o.isHemisphereLight);
 const sunDirection=new THREE.Vector3(-.65,.32,-.5).normalize();
 const skyUniforms={uNight:{value:0},uSun:{value:sunDirection},uTime:{value:0}};
 const sky=new THREE.Mesh(new THREE.SphereGeometry(230,32,24),new THREE.ShaderMaterial({side:THREE.BackSide,depthWrite:false,uniforms:skyUniforms,vertexShader:`varying vec3 vDirection;void main(){vDirection=position;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}`,fragmentShader:`precision highp float;
 varying vec3 vDirection;uniform float uNight;uniform vec3 uSun;uniform float uTime;
 float hash(vec3 p){p=fract(p*.3183099+vec3(.1,.2,.3));p*=17.;return fract(p.x*p.y*p.z*(p.x+p.y+p.z));}
 void main(){vec3 d=normalize(vDirection);float h=max(d.y,0.);vec3 horizon=mix(vec3(.99,.70,.43),vec3(.065,.13,.21),uNight);vec3 zenith=mix(vec3(.19,.45,.61),vec3(.008,.022,.07),uNight);vec3 c=mix(horizon,zenith,pow(h,.48));float a=max(dot(d,uSun),0.);c+=vec3(1.,.64,.30)*pow(a,10.)*.30*(1.-uNight);c+=vec3(1.,.84,.53)*smoothstep(.9986,.9995,a)*(1.-uNight)*2.;vec3 md=normalize(vec3(.38,.55,-.7));float moon=smoothstep(.9990,.9994,dot(d,md));c+=vec3(.73,.85,1.)*moon*uNight*1.6;vec3 grid=floor(d*480.);float star=step(.9978,hash(grid))*pow(max(0.,1.-length(fract(d*480.)-.5)*1.8),5.);c+=star*uNight*step(.07,d.y)*(1.5+.5*sin(uTime+hash(grid)*40.));gl_FragColor=vec4(c,1.);}` }));sky.frustumCulled=false;scene.add(sky);scene.add(sun.target);scene.background=null;scene.fog=new THREE.FogExp2(0xd3b99b,.0075);
 // Open water: animated normals, Fresnel sky reflection, sun glints and coastal foam.
 const seaUniforms={uTime:{value:0},uNight:{value:0},uSun:{value:sunDirection}};
 water.material.dispose();water.geometry.dispose();water.geometry=new THREE.PlaneGeometry(400,400,180,180);
 water.material=new THREE.ShaderMaterial({uniforms:seaUniforms,side:THREE.DoubleSide,vertexShader:`uniform float uTime;varying vec3 vWorld;void main(){vec3 p=position;p.z+=sin(p.x*.32+uTime*.75)*.10+cos(p.y*.25+uTime*.55)*.13+sin(p.x*.7+p.y*.38+uTime)*.035;vec4 w=modelMatrix*vec4(p,1.);vWorld=w.xyz;gl_Position=projectionMatrix*viewMatrix*w;}`,fragmentShader:`precision highp float;uniform float uTime;uniform float uNight;uniform vec3 uSun;varying vec3 vWorld;
 void main(){vec2 p=vWorld.xz;float nx=cos(p.x*.32+uTime*.75)*.032+cos(p.x*.7+p.y*.38+uTime)*.024;float nz=sin(p.y*.25-uTime*.55)*.032+cos(p.x*.7+p.y*.38+uTime)*.013;vec3 n=normalize(vec3(-nx,1.,-nz));vec3 v=normalize(cameraPosition-vWorld);float fres=pow(1.-max(dot(n,v),0.),3.);vec3 base=mix(vec3(.055,.37,.40),vec3(.015,.10,.17),uNight);vec3 reflectSky=mix(vec3(.85,.66,.44),vec3(.13,.23,.38),uNight);vec3 col=mix(base,reflectSky,fres*.85);vec3 l=normalize(mix(uSun,normalize(vec3(.38,.55,-.7)),uNight));float spec=pow(max(dot(n,normalize(l+v)),0.),220.);col+=mix(vec3(1.2,.83,.41),vec3(.65,.79,1.),uNight)*spec*.8;float edge=min(max(abs(p.x)-28.,abs(p.y)-24.),max(abs(p.x-135.)-36.,abs(p.y)-34.));float shoreline=(1.-smoothstep(0.,2.6,edge))*step(-.5,edge);float foam=smoothstep(.7,.98,sin(edge*4.-uTime*1.5+sin(p.x*.6)*.4));col=mix(col,mix(vec3(.75,.88,.76),vec3(.22,.40,.47),uNight),shoreline*foam*.65);float rip=sin(p.x*2.4+sin(p.y*1.3)+uTime)*sin(p.y*1.7-uTime*.7);col+=rip*.015;float fog=1.-exp(-length(cameraPosition-vWorld)*.004);col=mix(col,mix(vec3(.80,.68,.53),vec3(.045,.085,.15),uNight),fog);gl_FragColor=vec4(col,1.);}`});
 // Dense, individually colored grass uses a single instanced draw.
 const grassCount=mobile?2000:5200,grassGeo=new THREE.PlaneGeometry(.15,.52,1,3);grassGeo.translate(0,.26,0);
 const grassMat=new THREE.MeshStandardMaterial({color:0x9caf50,side:THREE.DoubleSide,roughness:.92});const grassTime={value:0};
 grassMat.onBeforeCompile=shader=>{shader.uniforms.uWindTime=grassTime;shader.vertexShader='uniform float uWindTime;\n'+shader.vertexShader;shader.vertexShader=shader.vertexShader.replace('#include <begin_vertex>',`#include <begin_vertex>
 vec3 origin=instanceMatrix[3].xyz;float wind=sin(uWindTime*1.6+origin.x*.45+origin.z*.3);transformed.x+=wind*pow(position.y,2.)*.55;transformed.z+=cos(uWindTime+origin.z*.6)*pow(position.y,2.)*.2;`)};
 const grass=new THREE.InstancedMesh(grassGeo,grassMat,grassCount);grass.receiveShadow=true;const dummy=new THREE.Object3D(),color=new THREE.Color();let gi=0;
 for(let i=0;gi<grassCount&&i<grassCount*9;i++){let x=(rand()-.5)*49,z=(rand()-.5)*39;if(((x+14)/4.1)**2+((z-10)/3.4)**2<1||(z>=-17&&z<=5&&Math.abs(x-23-Math.sin(z*.23)*.65)<1.35)||Math.abs(x)<3.4||Math.abs(z+1)<3||(z>7.4&&z<12.7&&x>0)||(x>-.8&&x<9&&z>-1&&z<11)||colliders.some(c=>c.w&&Math.abs(x-c.x)<c.w+.5&&Math.abs(z-c.z)<c.d+.5))continue;dummy.position.set(x,.19,z);dummy.rotation.set(0,rand()*Math.PI,0);dummy.scale.setScalar(.65+rand()*1.2);dummy.updateMatrix();grass.setMatrixAt(gi,dummy.matrix);color.setHSL(.19+rand()*.045,.35+rand()*.2,.28+rand()*.14);grass.setColorAt(gi++,color)}grass.count=gi;grass.computeBoundingSphere();scene.add(grass);
 // Stratified sea cliffs. Columns preserve the voxel character at many scales.
 for(let i=0;i<75;i++){let x=-30+rand()*60,z=i%2?-24-rand()*3:24+rand()*3;if(x>13&&x<21&&z>0)continue;let h=1.2+rand()*2.1;box(x,-2.4,z,1.3+rand()*2,h,1.5+rand()*2,[0x8c8972,0xa5a082,0xbeb28d][i%3]);box(x,-2.4+h/2,z,1.4,.14,1.6,0xd1bf94)}
 // A monumental offshore stone arch and distant rock spires.
 for(let i=0;i<8;i++){let x=52+i*2;box(x,2+Math.sin(i/7*Math.PI)*9,-22,2.3,5,5,0x89988b)}for(const x of[52,66]){box(x,0,-22,5,15,7,0x829185);box(x,7.9,-22,5.4,.8,7.2,0x82985c)}
 for(let i=0;i<18;i++){let x=-85+i*9,z=-66-rand()*15;let h=12+rand()*20;for(let j=0;j<4;j++)box(x+j*.4,h*j/6-5,z,10-j*1.8,h/3,8-j,0x79948b)}
 // Detailed roof ridges, stone walks, market produce, and a reading garden.
 for(const [x,z,w]of[[-12,-5,7],[13,-7,6.5]]){for(let j=0;j<10;j++){box(x,6.2,z-3+j*.66,.6,.16,.52,0x8c6749)}for(let j=0;j<6;j++){box(x-2.5+j, .35,z+4.5,.86,.08,1.15,j%2?0xbeb89a:0xcec8ab)}}
 for(let i=0;i<3;i++){box(-17+i*1.4,.8,0,1.15,1.1,1,0x94764e);box(-17+i*1.4,1.39,0,1.2,.1,1.1,0xb9a071);for(let j=0;j<6;j++)box(-17.35+i*1.4+(j%3)*.31,1.55,-.25+Math.floor(j/3)*.42,.25,.23,.3,[0xd89d46,0xbc7152,0x90a354][i])}
 for(const [x,z]of[[-5,11],[8,-5],[-7,-10]]){box(x,.75,z,2.7,.22,.9,0xa58c62);box(x,1.3,z-.45,2.7,.75,.15,0xa58c62);box(x-1,.4,z,.18,.7,.6,0x5b6651);box(x+1,.4,z,.18,.7,.6,0x5b6651)}
 // A little campfire has a warm light, rising embers and billowing smoke.
 const fire=new THREE.Group();fire.position.set(7,.2,-15);scene.add(fire);for(let i=0;i<10;i++){const a=i/10*Math.PI*2;box(7+Math.cos(a)*.85,.35,-15+Math.sin(a)*.85,.4,.35,.4,0x8c917c)}box(7,.4,-15,1,.24,.26,0x6c553c).rotation.y=.7;box(7,.52,-15,1,.24,.26,0x6c553c).rotation.y=-.7;
 const flameMat=new THREE.MeshStandardMaterial({color:0xffc66a,emissive:0xff7528,emissiveIntensity:2.3});const flame=new THREE.Mesh(new THREE.OctahedronGeometry(.43,0),flameMat);flame.position.set(7,.95,-15);flame.scale.set(.7,1.8,.7);scene.add(flame);const firelight=new THREE.PointLight(0xffa449,12,12,2);firelight.position.set(7,1.5,-15);scene.add(firelight);
 const lanterns=[];for(let i=0;i<7;i++){let x=i%2?-5:8,z=-6+i*4;let l=new THREE.PointLight(0xffcd7e,0,8,2);l.position.set(x,3,z);scene.add(l);lanterns.push(l)}
 const glows=[];scene.traverse(o=>{if(o.isMesh&&o.material?.color){const c=o.material.color.getHex();if([0xf1d496,0xffdc8c].includes(c)){o.material=o.material.clone();o.material.emissive=new THREE.Color(0xffb65c);glows.push(o.material)}}});
 const particleCount=mobile?70:170,positions=new Float32Array(particleCount*3),originals=[];for(let i=0;i<particleCount;i++){let p=[(rand()-.5)*48,.8+rand()*5,-3-rand()*17];positions.set(p,i*3);originals.push(p)}const pg=new THREE.BufferGeometry();pg.setAttribute('position',new THREE.BufferAttribute(positions,3));const pm=new THREE.ShaderMaterial({transparent:true,depthWrite:false,blending:THREE.AdditiveBlending,uniforms:{uTime:{value:0},uNight:{value:0}},vertexShader:`uniform float uTime;varying float vPulse;void main(){vec4 p=modelViewMatrix*vec4(position,1.);vPulse=.4+.6*sin(uTime*1.5+position.x)*sin(uTime*1.5+position.x);gl_PointSize=clamp(70./-p.z,1.,7.);gl_Position=projectionMatrix*p;}`,fragmentShader:`uniform float uNight;varying float vPulse;void main(){float d=length(gl_PointCoord-.5);float a=pow(max(0.,1.-d*2.),2.)*vPulse*(.14+uNight*.86);gl_FragColor=vec4(1.,.84,.40,a);}`});const particles=new THREE.Points(pg,pm);scene.add(particles);
 const smokeGeo=new THREE.BufferGeometry(),smokePos=new Float32Array(24*3);smokeGeo.setAttribute('position',new THREE.BufferAttribute(smokePos,3));const smokeMat=new THREE.PointsMaterial({color:0xb5b3a3,transparent:true,opacity:.14,size:.75,depthWrite:false});const smoke=new THREE.Points(smokeGeo,smokeMat);scene.add(smoke);
 // Offscreen bloom and a restrained filmic grade, downsampled for mobile.
 const hdr=renderer.extensions.has('EXT_color_buffer_float')||renderer.extensions.has('EXT_color_buffer_half_float');
 const rt=new THREE.WebGLRenderTarget(1,1,{depthBuffer:true,type:hdr?THREE.HalfFloatType:THREE.UnsignedByteType});const postScene=new THREE.Scene(),postCamera=new THREE.OrthographicCamera(-1,1,1,-1,0,1);
 const postMat=new THREE.ShaderMaterial({depthTest:false,depthWrite:false,uniforms:{uImage:{value:rt.texture},uResolution:{value:new THREE.Vector2(1,1)},uBloom:{value:.20},uNight:{value:0},uExposure:{value:1.12}},vertexShader:`varying vec2 vUv;void main(){vUv=uv;gl_Position=vec4(position.xy,0.,1.);}`,fragmentShader:`precision highp float;varying vec2 vUv;uniform sampler2D uImage;uniform vec2 uResolution;uniform float uBloom;uniform float uNight;uniform float uExposure;
 vec3 bright(vec2 p){vec3 c=texture2D(uImage,p).rgb;return c*max(0.,max(c.r,max(c.g,c.b))-.76);}
 void main(){vec2 px=1./uResolution;vec3 c=texture2D(uImage,vUv).rgb;vec3 bloom=vec3(0.);for(int i=1;i<=4;i++){float r=float(i)*3.;bloom+=bright(vUv+vec2(px.x*r,0.))+bright(vUv-vec2(px.x*r,0.))+bright(vUv+vec2(0.,px.y*r))+bright(vUv-vec2(0.,px.y*r));}c+=bloom*uBloom*.28;c*=uExposure;c=clamp((c*(2.51*c+.03))/(c*(2.43*c+.59)+.14),0.,1.);c=mix(vec3(dot(c,vec3(.2126,.7152,.0722))),c,1.06);c=(c-.5)*1.045+.5;c*=vec3(1.025,1.,.965+uNight*.065);float vignette=1.-smoothstep(.27,.85,length(vUv-.5))*.15;c*=vignette;gl_FragColor=vec4(c,1.);
 #include <colorspace_fragment>
 }`});postScene.add(new THREE.Mesh(new THREE.PlaneGeometry(2,2),postMat));
 function resize(){const scale=state.quality==='high'?Math.min(devicePixelRatio,1.8):Math.min(devicePixelRatio,1.15);renderer.setPixelRatio(scale);renderer.setSize(innerWidth,innerHeight);rt.setSize(Math.floor(innerWidth*scale),Math.floor(innerHeight*scale));postMat.uniforms.uResolution.value.set(rt.width,rt.height)}resize();addEventListener('resize',resize);
 function setQuality(){state.quality=state.quality==='high'?'balanced':'high';document.querySelector('#quality-toggle').textContent=state.quality==='high'?'描画：高品質':'描画：軽量';grass.count=state.quality==='high'?gi:Math.min(gi,2000);renderer.shadowMap.enabled=true;postMat.uniforms.uBloom.value=state.quality==='high'?.20:.1;resize();toast(state.quality==='high'?'高品質モードに切り替えました':'描画負荷を抑えた軽量モードに切り替えました')}
 document.querySelector('#quality-toggle').textContent=state.quality==='high'?'描画：高品質':'描画：軽量';
 document.querySelector('#quality-toggle').onclick=setQuality;
 document.querySelector('#time-toggle').onclick=()=>{state.targetNight=state.targetNight?0:1;document.querySelector('#time-toggle').innerHTML=state.targetNight?'☾ 夜の島':'☀ 夕暮れ';document.querySelector('#time-toggle').setAttribute('aria-pressed',String(!!state.targetNight));toast(state.targetNight?'灯りをたどって、夜の島を探検しよう。':'夕暮れの島に切り替えました')};
 document.querySelector('#view-toggle').onclick=()=>{state.firstPerson=!state.firstPerson;document.querySelector('#view-toggle').textContent=state.firstPerson?'◉ 一人称':'⌖ 俯瞰';document.body.classList.toggle('first-person',state.firstPerson);toast(state.firstPerson?'一人称視点。画面をドラッグして周囲を見渡せます。':'俯瞰視点に戻りました')};
 document.querySelector('#cinema-toggle').onclick=()=>{state.immersive=!state.immersive;document.body.classList.toggle('immersive',state.immersive);document.querySelector('#cinema-toggle').textContent=state.immersive?'画面を戻す':'景色に集中';document.querySelector('#cinema-toggle').setAttribute('aria-pressed',String(state.immersive))};
 addEventListener('keydown',e=>{if(document.querySelector('dialog[open]')||(document.body.classList.contains('on-journey')||document.body.classList.contains('is-fishing')))return;if(e.key.toLowerCase()==='v')document.querySelector('#view-toggle').click();if(e.key.toLowerCase()==='h')document.querySelector('#cinema-toggle').click()});
 function update(t,dt){state.time=t;state.night=THREE.MathUtils.damp(state.night,state.targetNight,1.4,dt);const n=state.night;sky.position.copy(camera.position);skyUniforms.uNight.value=n;skyUniforms.uTime.value=t;seaUniforms.uNight.value=n;seaUniforms.uTime.value=t;grassTime.value=t;pm.uniforms.uNight.value=n;pm.uniforms.uTime.value=t;postMat.uniforms.uNight.value=n;postMat.uniforms.uExposure.value=THREE.MathUtils.lerp(1.12,1.03,n);hemi.intensity=THREE.MathUtils.lerp(1.5,.58,n);hemi.color.setHex(0xd6e9f1).lerp(new THREE.Color(0x6086bc),n);hemi.groundColor.setHex(0x7b794c).lerp(new THREE.Color(0x233747),n);sun.intensity=THREE.MathUtils.lerp(3.4,.7,n);sun.color.setHex(0xffd19b).lerp(new THREE.Color(0x9ebfea),n);const focus=state.focusCenter||{x:camera.position.x>85?135:0,z:0};sun.position.set(focus.x-35,27,focus.z-25);sun.target.position.set(focus.x,0,focus.z);sun.target.updateMatrixWorld();scene.fog.color.setHex(0xd3b99b).lerp(new THREE.Color(0x142538),n);renderer.toneMappingExposure=THREE.MathUtils.lerp(1.12,1.03,n);lanterns.forEach(l=>l.intensity=n*11);glows.forEach(m=>m.emissiveIntensity=.15+n*1.9);firelight.intensity=(9+Math.sin(t*12)*2)*(1+n*.5);flame.scale.y=1.7+Math.sin(t*13)*.22;flame.rotation.y=t*.7;for(let i=0;i<particleCount;i++){const p=originals[i];positions[i*3]=p[0]+Math.sin(t*.33+i)*.6;positions[i*3+1]=p[1]+Math.sin(t*.65+i)*.3;positions[i*3+2]=p[2]+Math.cos(t*.3+i)*.5}pg.attributes.position.needsUpdate=true;for(let i=0;i<24;i++){const h=(t*.45+i*.2)%5;smokePos[i*3]=7+Math.sin(i+t*.25)*h*.16;smokePos[i*3+1]=1+h;smokePos[i*3+2]=-15+Math.cos(i)*h*.13}smokeGeo.attributes.position.needsUpdate=true;smoke.geometry.computeBoundingSphere();}
 function render(indoorScene=null){const night=postMat.uniforms.uNight.value,exposure=postMat.uniforms.uExposure.value,tone=renderer.toneMappingExposure;if(indoorScene){postMat.uniforms.uNight.value=0;postMat.uniforms.uExposure.value=1.08;renderer.toneMappingExposure=1.08}renderer.setRenderTarget(rt);renderer.render(indoorScene||scene,camera);renderer.setRenderTarget(null);renderer.render(postScene,postCamera);postMat.uniforms.uNight.value=night;postMat.uniforms.uExposure.value=exposure;renderer.toneMappingExposure=tone}
 return {state,update,render};
}
